/* ══ BOOKING FORM — Web3Forms ══ */
async function submitBooking(e) {
  e.preventDefault();
  const form    = document.getElementById('bookingForm');
  const confirm = document.getElementById('bookingConfirm');
  const btn     = document.getElementById('submitBtn');

  // Button loading state
  btn.textContent   = 'Sending…';
  btn.style.opacity = '0.6';
  btn.disabled      = true;

  try {
    const formData = new FormData(form);
    const object   = {};
    formData.forEach((v, k) => { object[k] = v; });

    // Set reply-to as client's email so you can reply directly from inbox
    object['replyto'] = object['email'] || '';

    const res  = await fetch('https://api.web3forms.com/submit', {
      method:  'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
      body:    JSON.stringify(object),
    });
    const json = await res.json();

    if(res.ok && json.success){
      // ✅ Success — show confirmation panel
      form.style.display = 'none';
      confirm.classList.add('show');
    } else {
      // ⚠ Web3Forms returned an error
      btn.textContent   = 'Try Again →';
      btn.style.opacity = '1';
      btn.disabled      = false;
      alert('Submission error: ' + (json.message || 'Please try again.'));
    }
  } catch(err) {
    // Network / fetch error
    btn.textContent   = 'Try Again →';
    btn.style.opacity = '1';
    btn.disabled      = false;
    alert('Network error. Please check your connection and try again.');
  }
}

/* ══ SPA ROUTER ══ */
const pages = ['home','about','work','services','articles','reviews','website','contact'];

function showPage(id, linkEl, options = {}) {
  if (!pages.includes(id)) id = 'home';

  // Hide all pages
  pages.forEach(p => {
    const el = document.getElementById('page-' + p);
    if (el) { el.classList.remove('active'); }
  });

  // Show target
  const target = document.getElementById('page-' + id);
  if (target) {
    target.classList.add('active');
    // Restart animation
    target.style.animation = 'none';
    target.offsetHeight; // reflow
    target.style.animation = '';
  }

  if (id === 'home' && typeof window.resetHeroCamera === 'function') {
    window.resetHeroCamera();
  }

  // Keep shareable URLs without forcing the browser to jump to anchors.
  if (!options.skipHash) {
    const nextHash = '#' + id;
    if (window.location.hash !== nextHash) {
      history.pushState(null, '', nextHash);
    }
  }

  // Scroll to top
  window.scrollTo({ top: 0, behavior: 'smooth' });

  // Update nav active state. Only actual nav links receive nav-active.
  document.querySelectorAll('.nav-links a').forEach(a => a.classList.remove('nav-active'));
  const navCandidate = linkEl && linkEl.closest && linkEl.closest('.nav-links') ? linkEl : null;
  if (navCandidate) {
    navCandidate.classList.add('nav-active');
  } else {
    document.querySelectorAll('.nav-links a').forEach(a => {
      const href = a.getAttribute('href') || '';
      const onclick = a.getAttribute('onclick') || '';
      if (href === '#' + id || onclick.includes("'" + id + "'")) {
        a.classList.add('nav-active');
      }
    });
  }

  // Re-trigger reveal animations for the new page
  setTimeout(() => {
    const reveals = target ? target.querySelectorAll('.reveal') : [];
    reveals.forEach((el, i) => {
      el.classList.remove('visible');
      setTimeout(() => el.classList.add('visible'), i * 80);
    });

    // Re-trigger skill bars
    if (id === 'services' && target) {
      target.querySelectorAll('.skill-bar-fill').forEach(bar => {
        bar.classList.remove('animated');
        setTimeout(() => bar.classList.add('animated'), 300);
      });
    }

    // Re-trigger testimonial animations
    if (id === 'reviews' && target) {
      target.querySelectorAll('.testi-card').forEach((card, i) => {
        card.classList.add(i % 2 === 0 ? 'hidden-left' : 'hidden-right');
        setTimeout(() => card.classList.remove('hidden-left', 'hidden-right'), i * 150 + 100);
      });
    }
  }, 50);

  return false;
}


function routeFromHash() {
  const id = (window.location.hash || '#home').slice(1);
  showPage(pages.includes(id) ? id : 'home', null, { skipHash: true });
}
window.addEventListener('popstate', routeFromHash);
if (window.location.hash) {
  routeFromHash();
} else {
  history.replaceState(null, '', '#home');
}

// Logo click goes home
